/** Type surface of the Remotion shim generated by visual-sandbox.ts (browser scenes only). */
import type React from 'react';
export const useCurrentFrame: () => number;
export const useVideoConfig: () => { fps: number; width: number; height: number; durationInFrames: number };
export const AbsoluteFill: React.FC<{ style?: React.CSSProperties; children?: React.ReactNode }>;
export const Sequence: React.FC<{ from: number; durationInFrames: number; children?: React.ReactNode }>;
type EasingFn = (t: number) => number;
export function interpolate(
  v: number,
  input: number[],
  output: number[],
  opts?: { extrapolateLeft?: 'clamp' | 'extend'; extrapolateRight?: 'clamp' | 'extend'; easing?: EasingFn },
): number;
export const Easing: {
  linear: EasingFn; ease: EasingFn; quad: EasingFn; cubic: EasingFn; sin: EasingFn; exp: EasingFn;
  in: (fn: EasingFn) => EasingFn; out: (fn: EasingFn) => EasingFn; inOut: (fn: EasingFn) => EasingFn;
};
export function random(seed: string | number): number;
export function spring(opts: { frame: number; fps: number; config?: { damping?: number; stiffness?: number } }): number;
